<script lang="ts">
 import {onMount,tick,untrack} from 'svelte';
 import {Search,Plus,Minus,Scan,Layers,Box,Clapperboard,Package,MessageCircle,GripVertical} from 'lucide-svelte';
 import type {Adventure} from '../demo/adventure';
 import type {PixelArtPack} from '@isometrico/world';
 import SpriteThumbnail from '$lib/components/SpriteThumbnail.svelte';
 import {workshopNpc} from '../workshop/resources';
 import {storyBoard,filterBoard,boardPositions,type BoardSelection,type BoardNode} from './board';
 let {adventure,graphics,selected='',onselect,onlayout}:{adventure:Adventure;graphics:PixelArtPack;selected?:string;onselect:(selection:BoardSelection,relationship?:boolean)=>void;onlayout:(positions:Record<string,{x:number;y:number}>)=>void}=$props();
 let map=$state(''),query=$state(''),allObjects=$state(false),scale=$state(.9),pan=$state({x:20,y:20}),viewport=$state<HTMLElement>();
 let dragged=$state<{id:string;x:number;y:number}|null>(null);
 let gesture:{id?:string;start:{x:number;y:number};base:{x:number;y:number};moved:boolean;pointer:number;capture:HTMLElement}|undefined;
 let suppressClick=false;
 const board=$derived(storyBoard(adventure)),selectedGroup=$derived(board.nodes.find(node=>node.id===selected)?.mapId??''),visible=$derived(filterBoard(board,map,query,allObjects));
 const basePositions=$derived(boardPositions([...board.nodes].sort((a,b)=>Number(b.configured)-Number(a.configured)),adventure.story?.layout));
 const positions=$derived(dragged?{...basePositions,[dragged.id]:{x:dragged.x,y:dragged.y}}:basePositions);
 const bounds=$derived.by(()=>{const points=visible.nodes.map(node=>positions[node.id]);const x=points.length?Math.min(...points.map(p=>p.x))-20:0,y=points.length?Math.min(...points.map(p=>p.y))-20:0;return {x,y,width:Math.max(300,...points.map(p=>p.x+244-x)),height:Math.max(220,...points.map(p=>p.y+162-y))};});
 const canvasSize=$derived({width:Math.max(700,...Object.values(positions).map(p=>p.x+360)),height:Math.max(400,...Object.values(positions).map(p=>p.y+230))});
 function zoom(delta:number){const next=Math.min(1.8,Math.max(.25,scale+delta)),width=viewport?.clientWidth??700,height=viewport?.clientHeight??400;pan={x:width/2-(width/2-pan.x)*next/scale,y:height/2-(height/2-pan.y)*next/scale};scale=next;}
 function fit(){if(!viewport)return;scale=Math.min(1.2,Math.max(.25,Math.min((viewport.clientWidth-32)/bounds.width,(viewport.clientHeight-32)/bounds.height)));pan={x:(viewport.clientWidth-bounds.width*scale)/2-bounds.x*scale,y:(viewport.clientHeight-bounds.height*scale)/2-bounds.y*scale};}
 function autoArrange(){onlayout(boardPositions(visible.nodes));pan={x:20,y:20};}
 function begin(e:PointerEvent,id?:string){if(e.button!==0)return;e.stopPropagation();const base=id?positions[id]:pan;gesture={id,start:{x:e.clientX,y:e.clientY},base:{...base},moved:false,pointer:e.pointerId,capture:e.currentTarget as HTMLElement};if(id)dragged={id,...base};gesture.capture.setPointerCapture(e.pointerId);}
 function move(e:PointerEvent){if(!gesture||gesture.pointer!==e.pointerId)return;const dx=e.clientX-gesture.start.x,dy=e.clientY-gesture.start.y;gesture.moved ||= Math.abs(dx)+Math.abs(dy)>5;if(gesture.id)dragged={id:gesture.id,x:Math.max(0,gesture.base.x+dx/scale),y:Math.max(0,gesture.base.y+dy/scale)};else pan={x:gesture.base.x+dx,y:gesture.base.y+dy};}
 function end(e:PointerEvent){if(!gesture||gesture.pointer!==e.pointerId)return;const current=gesture;gesture=undefined;if(current.id&&current.moved&&dragged){onlayout({[current.id]:{x:Math.round(dragged.x/16)*16,y:Math.round(dragged.y/16)*16}});suppressClick=true;setTimeout(()=>suppressClick=false,0);}dragged=null;if(current.capture.hasPointerCapture(e.pointerId))current.capture.releasePointerCapture(e.pointerId);}
 function choose(node:BoardNode){if(!suppressClick)onselect(node.selection);}
 function nodeKeys(e:KeyboardEvent,node:BoardNode){const axis=['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].indexOf(e.key);if(axis<0)return;e.preventDefault();e.stopPropagation();const p=positions[node.id];onlayout({[node.id]:{x:Math.max(0,p.x+(axis===0?-16:axis===1?16:0)),y:Math.max(0,p.y+(axis===2?-16:axis===3?16:0))}});}
 function canvasKeys(e:KeyboardEvent){if(e.target!==viewport)return;const changes:Record<string,{x:number;y:number}>={ArrowLeft:{x:32,y:0},ArrowRight:{x:-32,y:0},ArrowUp:{x:0,y:32},ArrowDown:{x:0,y:-32}};if(changes[e.key]){e.preventDefault();pan={x:pan.x+changes[e.key].x,y:pan.y+changes[e.key].y};}}
 function wheel(node:HTMLElement){const handler=(event:WheelEvent)=>{event.preventDefault();zoom(event.deltaY>0?-.1:.1);};node.addEventListener('wheel',handler,{passive:false});return{destroy(){node.removeEventListener('wheel',handler);}};}
 function thumbnail(node:BoardNode){if(!node.visualId)return;const image=graphics.objects[node.visualId];if(image)return image;if(node.selection.kind==='object'){const ref=node.selection.ref,entity=adventure.maps.find(m=>m.id===ref.mapId)?.entities.find(e=>e.id===ref.entityId);if(entity?.kind==='person'){try{return workshopNpc(graphics,node.visualId);}catch{/* Legacy vector actors have no PNG thumbnail. */}}} }

 function wire(source:string,target:string){const a=positions[source],b=positions[target];if(!a||!b)return {path:'',x:0,y:0};if(source===target)return{path:`M ${a.x+224} ${a.y+38} C ${a.x+310} ${a.y-24},${a.x+310} ${a.y+156},${a.x+224} ${a.y+104}`,x:a.x+234,y:a.y+68};const from={x:a.x+224,y:a.y+70},to={x:b.x,y:b.y+70},bend=Math.max(60,Math.abs(to.x-from.x)*.45);return {path:`M ${from.x} ${from.y} C ${from.x+bend} ${from.y},${to.x-bend} ${to.y},${to.x} ${to.y}`,x:(from.x+to.x)/2,y:(from.y+to.y)/2};}
 function focusView(){void tick().then(fit);}
 function focusNode(id:string){const p=positions[id];if(!p||!viewport)return;scale=Math.max(scale,.75);pan={x:viewport.clientWidth/2-(p.x+112)*scale,y:viewport.clientHeight/2-(p.y+71)*scale};}
 $effect(()=>{const id=selected;selectedGroup;if(id)untrack(()=>{void tick().then(()=>focusNode(id));});});
 onMount(focusView);
</script>
<svelte:window onpointermove={move} onpointerup={end} onpointercancel={end}/>
<section class="story-board" aria-label="Guion de toda la aventura">
 <header><label class="search"><Search size={16}/><input aria-label="Buscar en el guion" placeholder="Buscar objeto, módulo o evento…" bind:value={query} oninput={focusView}/></label><select aria-label="Mapas del guion" bind:value={map} onchange={focusView}><option value="">Toda la aventura</option>{#each adventure.maps as m}<option value={m.id}>{m.name}</option>{/each}</select><label class="all"><input type="checkbox" bind:checked={allObjects} onchange={focusView}/> Todos los objetos</label><button onclick={autoArrange} title="Organizar las tarjetas automáticamente"><Layers size={15}/> Organizar</button></header>
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard-operable canvas; every node is a native button.) -->
 <!-- svelte-ignore a11y_no_noninteractive_element_interactions (Keyboard and pointer navigation belong to the canvas.) -->
 <div class="viewport" role="application" aria-label="Tablero de guion. Arrastra el fondo para desplazarte; selecciona una tarjeta para editar. Las flechas mueven una tarjeta enfocada." tabindex="0" bind:this={viewport} use:wheel onpointerdown={e=>{if(e.target===viewport)begin(e);}} onkeydown={canvasKeys}>
  <div class="canvas" style:width={canvasSize.width+'px'} style:height={canvasSize.height+'px'} style:transform={`translate(${pan.x}px,${pan.y}px) scale(${scale})`}>
   <svg class="connections" width={canvasSize.width} height={canvasSize.height} aria-hidden="true"><defs><marker id="story-board-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor"/></marker></defs>{#each visible.edges as edge (edge.id)}{@const line=wire(edge.source,edge.target)}<path d={line.path} class:requirement={edge.kind==='requirement'} marker-end="url(#story-board-arrow)"/>{/each}</svg>
   {#each visible.edges as edge (edge.id)}{@const line=wire(edge.source,edge.target)}<button class="edge" class:requirement={edge.kind==='requirement'} style:left={line.x+'px'} style:top={line.y+'px'} title={edge.label} aria-label={'Editar relación: '+edge.label} onclick={()=>onselect(edge.owner,true)}>{edge.label}</button>{/each}
   {#each visible.nodes as node (node.id)}{@const p=positions[node.id]}{@const image=thumbnail(node)}<button class="node" class:selected={node.id===selected} class:event={node.selection.kind==='event'} class:map={node.selection.kind==='map'} style:left={p.x+'px'} style:top={p.y+'px'} aria-label={'Editar '+node.title+' · '+node.location} title={node.title+' · '+node.location} onclick={()=>choose(node)} onpointerdown={e=>begin(e,node.id)} onkeydown={e=>nodeKeys(e,node)}>
    <span class="node-heading"><span class="thumb">{#if image}<SpriteThumbnail image={image.image} frame={image.frame} width={40} height={40}/>{:else if node.selection.kind==='event'}<Clapperboard size={22}/>{:else if node.selection.kind==='map'}<Layers size={22}/>{:else if node.selection.kind==='item'}<Package size={22}/>{:else}<Box size={22}/>{/if}</span><span class="node-name"><strong>{node.title}</strong><small>{node.location}</small></span><GripVertical size={13}/></span>
    <span class="action">{node.action}</span><span class="module">{#if node.modules.length}<MessageCircle size={12}/>{node.modules[0]}{node.modules.length>1?' +'+(node.modules.length-1):''}{:else}{node.selection.kind==='map'?'Entradas y salidas':node.selection.kind==='item'?'Requisitos y recompensas':node.states.length?node.states.slice(0,2).join(' / '):'Sin módulos'}{/if}</span><span class="counts">{#if node.selection.kind==='object'}{node.states.length} estados · {node.modules.length} módulos{:else if node.selection.kind==='event'}Evento narrativo · {node.modules.length} módulos{:else if node.selection.kind==='map'}Mapa del guion{:else}Artículo de inventario{/if}</span>
   </button>{/each}
  </div>
  {#if !visible.nodes.length}<p class="empty">No hay elementos que coincidan.</p>{/if}
 </div>
 <footer><span>{visible.nodes.length} tarjetas · {visible.edges.length} relaciones</span><span class="legend"><i></i>Consecuencia <i class="dashed"></i>Requisito</span><div><button aria-label="Alejar guion" disabled={scale<=.25} onclick={()=>zoom(-.1)}><Minus size={16}/></button><output aria-label="Zoom del guion">{Math.round(scale*100)}%</output><button aria-label="Acercar guion" disabled={scale>=1.8} onclick={()=>zoom(.1)}><Plus size={16}/></button><button aria-label="Encajar guion" onclick={fit}><Scan size={16}/></button></div></footer>
</section>
<style>
 .story-board{display:flex;flex-direction:column;flex:1;min-height:0;height:100%;font-size:12px;color:#2b4133}header{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:10px 12px;background:#fbfcf9;border-bottom:1px solid #dce4d8;flex:none}.search{display:flex;gap:6px;align-items:center;flex:1;min-width:150px}.search input,select{min-width:0;box-sizing:border-box;padding:8px;border:1px solid #d8e0ce;border-radius:7px;background:#fff;font:inherit;color:#3e5334}.search input{width:100%}select{max-width:180px}.all{display:flex;align-items:center;gap:5px;font-size:11px;white-space:nowrap}.all input{margin:0}.viewport{flex:1;min-height:220px;position:relative;overflow:hidden;background:radial-gradient(#d7dfd0 1px,transparent 1px) 0 0/20px 20px;background-color:#eef3e9;touch-action:none;cursor:grab}.canvas{position:absolute;left:0;top:0;transform-origin:0 0;pointer-events:none}.connections{position:absolute;inset:0;overflow:visible;color:#8b9c7f}.connections>path{fill:none;stroke:currentColor;stroke-width:1.5}.connections>path.requirement{stroke-dasharray:5 4}.node{position:absolute;width:224px;height:142px;display:flex;flex-direction:column;align-items:stretch;gap:8px;padding:12px;box-sizing:border-box;border:1px solid #ccd9c4;border-radius:10px;background:#fbfcf9;box-shadow:0 3px 10px #233b2710;text-align:left;pointer-events:auto;cursor:grab;touch-action:none}.node.selected{border-color:#739350;box-shadow:0 0 0 2px #73935035}.node.event{background:#f5f0e8}.node.map{background:#e5edda}.node-heading{display:flex;align-items:center;gap:8px;min-height:40px}.thumb{width:36px;height:36px;display:grid;place-items:center;flex:none;color:#6a805e}.node-name{display:grid;gap:4px;min-width:0;flex:1}.node-name strong{font-size:13px;font-weight:600;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.node-name small{font-size:10px;color:#7b8973;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.action,.module{font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;display:flex;gap:4px;align-items:center;color:#64775a}.counts{font-size:10px;color:#85927b;margin-top:auto}.edge{position:absolute;max-width:190px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;transform:translate(-50%,-50%);padding:4px 6px;font-size:10px;background:#f5f8f0;border-color:#dde5d7;color:#677e5a;min-height:24px;pointer-events:auto;box-shadow:0 1px 4px #263b2e10}.edge.requirement{border-style:dashed}.empty{position:absolute;inset:40% 0 auto;text-align:center;color:#7b8973}footer{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:6px 12px;border-top:1px solid #dce4d8;background:#fbfcf9;flex:none;font-size:11px;color:#7b8973}footer>div{margin-left:auto;display:flex;align-items:center;gap:4px}output{min-width:40px;text-align:center}.legend{display:flex;align-items:center;gap:5px;font-size:10px}.legend i{width:16px;border-top:1px solid #8b9c7f}.legend i.dashed{border-top-style:dashed;margin-left:6px}button{display:inline-flex;align-items:center;gap:5px;padding:7px;border:1px solid #d8e0ce;border-radius:6px;background:#fffef9;color:inherit;font:inherit;cursor:pointer}button:disabled{opacity:.45;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible,.viewport:focus-visible{outline:2px solid #74994e;outline-offset:2px}@media(max-width:700px){header{padding:8px;gap:6px}.all{font-size:10px}.legend{display:none}select{max-width:150px}footer{padding:5px 8px}}
</style>
